PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS project_corpora (project_id TEXT PRIMARY KEY REFERENCES projects(id), source_mode TEXT NOT NULL CHECK(source_mode IN ('public-and-uploads','uploads-only')), dataset_id TEXT NOT NULL, dataset_version TEXT NOT NULL, notice TEXT NOT NULL, organization TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS members (project_id TEXT NOT NULL, user_id TEXT NOT NULL, role TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(project_id,user_id));
CREATE TABLE IF NOT EXISTS files (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, title TEXT NOT NULL, current_version TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS versions (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, file_id TEXT NOT NULL REFERENCES files(id), number INTEGER NOT NULL, filename TEXT NOT NULL, revision TEXT NOT NULL, dated TEXT NOT NULL, area TEXT NOT NULL, approval TEXT NOT NULL, kind TEXT NOT NULL, hash TEXT NOT NULL, text TEXT NOT NULL, state TEXT NOT NULL, error TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(file_id,number));
CREATE TABLE IF NOT EXISTS originals (version_id TEXT NOT NULL REFERENCES versions(id), part INTEGER NOT NULL, data TEXT NOT NULL, PRIMARY KEY(version_id,part));
CREATE TABLE IF NOT EXISTS chunks (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, version_id TEXT NOT NULL REFERENCES versions(id), file_id TEXT NOT NULL, position INTEGER NOT NULL, text TEXT NOT NULL);
CREATE VIRTUAL TABLE IF NOT EXISTS chunk_search USING fts5(id UNINDEXED, project_id UNINDEXED, version_id UNINDEXED, text);
CREATE TRIGGER IF NOT EXISTS chunks_insert AFTER INSERT ON chunks BEGIN INSERT INTO chunk_search(id,project_id,version_id,text) VALUES(new.id,new.project_id,new.version_id,new.text); END;
CREATE TABLE IF NOT EXISTS file_events (seq INTEGER PRIMARY KEY AUTOINCREMENT, project_id TEXT NOT NULL, version_id TEXT NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS activations (event_seq INTEGER PRIMARY KEY REFERENCES file_events(seq), project_id TEXT NOT NULL, file_id TEXT NOT NULL, version_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS records (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, owner_id TEXT NOT NULL, owner_role TEXT NOT NULL, question TEXT NOT NULL, result TEXT NOT NULL, shared INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reviews (id TEXT PRIMARY KEY, record_id TEXT NOT NULL REFERENCES records(id), project_id TEXT NOT NULL, actor_id TEXT NOT NULL, role TEXT NOT NULL, decision TEXT NOT NULL, note TEXT NOT NULL, checked_ids TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS monitors (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, owner_id TEXT NOT NULL, record_id TEXT NOT NULL UNIQUE REFERENCES records(id), state TEXT NOT NULL, cursor INTEGER NOT NULL, checked_at TEXT, next_check TEXT NOT NULL, error TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS runs (id TEXT PRIMARY KEY, monitor_id TEXT NOT NULL REFERENCES monitors(id), project_id TEXT NOT NULL, event_seq INTEGER NOT NULL, event_key TEXT NOT NULL, trigger TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, lease_until TEXT, heartbeat TEXT, activity TEXT NOT NULL DEFAULT '[]', result TEXT, error TEXT, started_at TEXT, completed_at TEXT, available_at TEXT NOT NULL, UNIQUE(monitor_id,event_key));
CREATE TABLE IF NOT EXISTS updates (id TEXT PRIMARY KEY, monitor_id TEXT NOT NULL REFERENCES monitors(id), record_id TEXT NOT NULL, project_id TEXT NOT NULL, owner_id TEXT NOT NULL, version_id TEXT NOT NULL, change_type TEXT NOT NULL, finding TEXT NOT NULL, evidence TEXT NOT NULL, old_evidence TEXT NOT NULL, run_id TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(monitor_id,version_id,change_type));
CREATE TABLE IF NOT EXISTS update_reviews (id TEXT PRIMARY KEY, update_id TEXT NOT NULL REFERENCES updates(id), project_id TEXT NOT NULL, actor_id TEXT NOT NULL, role TEXT NOT NULL, decision TEXT NOT NULL, note TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS records_owner ON records(project_id,owner_id,created_at);
CREATE INDEX IF NOT EXISTS versions_project ON versions(project_id,file_id,state);
CREATE INDEX IF NOT EXISTS events_project ON file_events(project_id,seq);
CREATE INDEX IF NOT EXISTS runs_pending ON runs(status,available_at,event_seq);
CREATE INDEX IF NOT EXISTS monitors_project ON monitors(project_id,state);
CREATE TABLE IF NOT EXISTS rfi_register (project_id TEXT NOT NULL REFERENCES projects(id), rfi_number TEXT NOT NULL, title TEXT NOT NULL, status TEXT NOT NULL, metadata TEXT NOT NULL, log_version_id TEXT NOT NULL REFERENCES versions(id), row_number INTEGER NOT NULL, PRIMARY KEY(project_id,rfi_number,row_number));
CREATE TABLE IF NOT EXISTS rfi_documents (version_id TEXT PRIMARY KEY REFERENCES versions(id), project_id TEXT NOT NULL, rfi_number TEXT NOT NULL, disposition TEXT NOT NULL DEFAULT 'record', replaced_by TEXT NOT NULL DEFAULT '', change_log TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS rfi_links (source_version_id TEXT NOT NULL REFERENCES versions(id), project_id TEXT NOT NULL, target_number TEXT NOT NULL, relation TEXT NOT NULL, reason TEXT NOT NULL, page INTEGER NOT NULL, PRIMARY KEY(source_version_id,target_number,relation));
CREATE INDEX IF NOT EXISTS rfi_documents_number ON rfi_documents(project_id,rfi_number);
